"""Build dated Viking/Renaissance editions from DARMC layers 8 and 14.
Run after downloading the GeoJSON queries to /private/tmp/atlas-era-{8,14}.json.
No modern borders are substituted; broad source regions remain identified.
"""
import json,re
from pathlib import Path
out=Path(__file__).resolve().parents[1]/'dist'
data=json.loads((out/'historical.json').read_text())
source='https://darmc.harvard.edu/map-sources'
met='https://www.metmuseum.org/essays/the-vikings-780-1100'
rena='https://www.metmuseum.org/essays/architecture-in-renaissance-italy'
trade='https://vikingar.historiska.se/objects.php?e=&l=en&showcase=37342b88-404e-4060-91c8-f2991d87a18f'
def slug(s):return re.sub('[^a-z0-9]+','-',s.lower()).strip('-')
def anchor(parts):
 ring=max((p[0] for p in parts),key=lambda r:abs(sum(a[0]*b[1]-b[0]*a[1] for a,b in zip(r,r[1:]))))
 area=cx=cy=0
 for a,b in zip(ring,ring[1:]):
  v=a[0]*b[1]-b[0]*a[1];area+=v;cx+=(a[0]+b[0])*v;cy+=(a[1]+b[1])*v
 return [cx/(3*area),cy/(3*area)] if area else ring[0]
for era,n in [('viking',8),('renaissance',14)]:
 groups={}
 for f in json.load(open(f'/private/tmp/atlas-era-{n}.json'))['features']:
  p=f['properties'];k=p['KINGDOMNAME'];r=p['REGIONNAME'].strip()
  # Preserve separately mapped Normandy and Scottish realms; split Islamic dynasties.
  name=r if k in ('United Kingdom','Belgium','Islamic World') or r=='Normandy' else k
  name={'Kiev Rus':'Kyivan Rus’','Venetian Areas':'Republic of Venice','Byzantine Areas':'Byzantine territories','England':'Kingdom of England','France':'Kingdom of France','Denmark':'Denmark','Norway':'Norway','Sweden':'Sweden'}.get(name,name)
  if not name:continue
  id=slug(name);g=groups.setdefault(id,{'name':name,'parts':[]});geom=f['geometry'];g['parts'].extend(geom['coordinates'] if geom['type']=='MultiPolygon' else [geom['coordinates']])
 features=[];labels=[]
 for i,(id,g) in enumerate(groups.items()):
  props={'id':id,'name':g['name'],'tone':i%6,'era':era};features.append({'type':'Feature','id':id,'properties':props,'geometry':{'type':'MultiPolygon','coordinates':g['parts']}});labels.append({'type':'Feature','properties':props,'geometry':{'type':'Point','coordinates':anchor(g['parts'])}})
 for suffix,fs in [('',features),('-labels',labels)]:
  (out/f'{era}-territories{suffix}.geojson').write_text(json.dumps({'type':'FeatureCollection','attribution':'Harvard DARMC / Mapping Past Societies; Darryl Campbell, Nathaniel Donoghue, Kelly Gibson, Matthew Polk. Approximate historical boundaries, ca. AD '+('1000' if n==8 else '1450')+'.','features':fs},ensure_ascii=False,separators=(',',':')))
 edition={'title':'The Viking Age' if era=='viking' else 'The Renaissance','date':'c. AD 1000' if era=='viking' else 'c. AD 1450','intro':'Trading ports, northern kingdoms and the journeys that connected them.' if era=='viking' else 'Cities of art, commerce and learning in a changing Europe.','scope':'Cities and historical territories','note':'Historical boundaries are approximate DARMC reconstructions. '+('This European map explores the wider Viking Age, not a single Viking empire. City questions include trading sites whose heyday predates AD 1000. North Atlantic settlements are outside this map’s coverage.' if era=='viking' else 'The map is dated ca. 1450, before the fall of Constantinople. Italian city-states are not separately resolved in this source: Florence and Milan sit within its broad Holy Roman Empire context, not a claim of direct imperial control. Facts may discuss later Renaissance developments, with dates stated.'),'source':source,'contextSource':source,'contextAttribution':'Harvard DARMC','bounds':[[-15,45],[43,68]] if era=='viking' else [[-12,30],[40,58]],'places':[]}
 def city(id,name,xy,modern,territory,fact,url):edition['places'].append(dict(id=id,name=name,kind='City',center=xy,modern=modern,territoryId=territory,fact=fact,source=url))
 def region(id,name,fact,url=source):edition['places'].append(dict(id=id,name=name,kind='Territory',center=anchor(groups[id]['parts']),modern='Approximate historical territory; see the dated map note.',territoryId=id,fact=fact,source=url))
 if era=='viking':
  city('hedeby','Hedeby',[9.56,54.49],'Near Schleswig, Germany','denmark','At the narrow neck of Jutland, Hedeby connected routes between the North Sea and the Baltic. Its harbour, streets and nearby Danevirke defences preserve evidence of a major Viking Age trading centre.','https://whc.unesco.org/en/list/1553/')
  city('birka','Birka',[17.54,59.33],'Björkö, Sweden','sweden','Birka and nearby Hovgården reveal the trading networks of Viking Scandinavia. Birka flourished chiefly in the eighth to tenth centuries; this is an earlier Viking Age site on the AD 1000 context map.','https://whc.unesco.org/en/list/555/')
  city('ribe','Ribe',[8.77,55.33],'Ribe, Denmark','denmark','Ribe was one of the town-like trading centres of Viking Scandinavia. Such settlements linked craft production and exchange across sea routes.',trade)
  city('kaupang','Kaupang',[10.1,59.03],'Near Larvik, Norway','norway','Kaupang, also associated with the name Skiringssal, was a Norwegian trading centre. It belongs to the earlier Viking Age network rather than a modern national capital.',trade)
  city('jelling','Jelling',[9.42,55.76],'Jelling, Denmark','denmark','The burial mounds, rune stones and church at Jelling illustrate Denmark’s transition toward Christianity and royal consolidation in the tenth century.','https://whc.unesco.org/en/list/697/')
  city('york','Jórvík / York',[-1.08,53.96],'York, England','kingdom-of-england','Scandinavian settlement transformed York into an important urban centre. By the map’s date it belonged to the English kingdom; the Viking Age question recalls its earlier Scandinavian connections.',met)
  city('dublin','Dyflin / Dublin',[-6.26,53.35],'Dublin, Ireland','ireland','A Viking fortified base was established at Dublin in 841. By the tenth century it was among the ports developing into Ireland’s first towns.','https://source.museum.ie/en-IE/Collections-Research/Irish-Antiquities-Division-Collections/Collections-List-%281%29/Viking/The-Viking-Age-in-Ireland')
  city('rouen','Rouen',[1.1,49.44],'Rouen, France','normandy','Normandy took its name from Scandinavian settlers. Their descendants became part of the Christian political world of western Europe rather than remaining a single overseas Viking state.',met)
  city('novgorod','Novgorod',[31.28,58.52],'Veliky Novgorod, Russia','kyivan-rus','Novgorod belonged to the eastern trading world linking Scandinavia with river routes into Rus’. The Viking Age extended through commerce and settlement as well as raiding.','https://whc.unesco.org/en/list/604/')
  city('kyiv','Kyiv',[30.52,50.45],'Kyiv, Ukraine','kyivan-rus','Kyiv was a major centre of Rus’. Scandinavian travellers formed part of a much wider eastern European world, whose societies cannot be reduced to a Viking colony.',met)
  for args in [('denmark','Denmark','Danish royal power grew during the Viking Age. Jelling provides physical evidence of tenth-century kingship and Christianization.','https://whc.unesco.org/en/list/697/'),('norway','Norway','Norway’s coasts connected communities by sea. Kaupang was one of the trading centres in the Scandinavian network.',trade),('sweden','Sweden','The Swedish region included trading networks represented by Birka and Hovgården. Viking Age Scandinavia was politically varied, not one unified empire.','https://whc.unesco.org/en/list/555/'),('normandy','Normandy','Scandinavian settlement in northern France helped form Normandy. Its later rulers participated in the Christian aristocratic culture of western Europe.',met),('kingdom-of-england','Kingdom of England','The AD 1000 map shows an English kingdom after the earlier Scandinavian settlement of places such as York. Viking Age raids, settlement and changing rule were distinct processes.',met),('kyivan-rus','Kyivan Rus’','Rus’ linked eastern European communities and long-distance river trade. Norse travellers were one part of its diverse history.',met)]:region(*args)
  edition['background']=[{'label':'More than raiders','text':'The Viking Age included farming, craft production, exchange, settlement and violence. Scandinavian societies were diverse; the shaded realms are historical context, not a single Viking empire.','source':met},{'label':'Reading this map','text':'Political context is ca. AD 1000. Earlier trading sites are retained as questions so you can explore the whole Viking Age.','source':source}]
  events=[('c. 790–1100','The broad Viking Age: Scandinavian journeys, settlement and exchange.'),('841','A Viking fortified base is established at Dublin.'),('10th century','Jelling records royal power and Christianization in Denmark.'),('c. 1000','The political snapshot used for this map.'),('c. 1000','Norse voyages reach North America, beyond this European map.')]
 else:
  rows=[('florence','Florence',[11.25,43.77],'Italy','holy-roman-empire','Florence became a leading centre of Renaissance art and humanist learning. Its classical revival was supported by patrons including the Medici; the map source groups this area broadly rather than drawing the Florentine state.',rena),('venice','Venice',[12.34,45.44],'Italy','republic-of-venice','Venice joined maritime commerce with a distinctive artistic culture. Its Renaissance painting developed across the fifteenth and early sixteenth centuries.','https://www.metmuseum.org/exhibitions/listings/2011/renaissance-venice'),('rome','Rome',[12.49,41.89],'Italy','papal-states','Rome’s ancient buildings and texts helped inspire Renaissance study. The papal city later drew major artistic and architectural commissions; those later projects should not be mistaken for completed works in 1450.',rena),('milan','Milan',[9.19,45.46],'Italy','holy-roman-empire','Milan was a major northern Italian court city. This source’s broad imperial polygon does not resolve its duchy as an independent selectable state.','https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/renaissance.pdf'),('naples','Naples',[14.27,40.85],'Italy','kingdom-of-naples','Naples was the centre of a southern Italian kingdom. Renaissance culture developed among competing courts and city-states, not within a unified Italian nation.',rena),('rimini','Rimini',[12.57,44.06],'Italy','papal-states','Alberti’s Tempio Malatestiano at Rimini, begun around 1450, reinterpreted the forms of Roman temple architecture.',rena),('paris','Paris',[2.35,48.86],'France','kingdom-of-france','Paris was a royal and intellectual centre. Renaissance ideas circulated across Europe at different times; the cultural label does not mean every region changed in the same year.','https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/renaissance.pdf'),('london','London',[-.13,51.51],'England','kingdom-of-england','London was England’s royal and commercial centre. This early Renaissance map predates the Tudor dynasty and the later Elizabethan cultural flowering.','https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/renaissance.pdf'),('lisbon','Lisbon',[-9.14,38.72],'Portugal','kingdom-of-portugal','Lisbon connected Portugal to Atlantic routes. The fifteenth century’s maritime expansion formed part of the wider world in which Renaissance Europe developed.','https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/renaissance.pdf'),('constantinople','Constantinople',[28.98,41.01],'Istanbul, Türkiye','byzantine-territories','In this ca. 1450 snapshot, Constantinople remains Byzantine. Its Ottoman conquest occurred in 1453, a crucial distinction when reading the map.','https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/renaissance.pdf'),('edirne','Edirne',[26.56,41.68],'Türkiye','ottoman-empire','Edirne was an Ottoman centre in the European Balkans. The Ottoman state was part of the Renaissance-era Mediterranean world, not outside its geography.','https://www.metmuseum.org/essays/the-art-of-the-ottomans-before-1600'),('mainz','Mainz',[8.27,50.0],'Germany','holy-roman-empire','Mainz is associated with Gutenberg’s printing enterprise. The Gutenberg Bible appeared in the 1450s, shortly after this map’s approximate date.','https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/renaissance.pdf')]
  for args in rows:city(*args)
  for id,name,fact in [('republic-of-venice','Republic of Venice','Venice governed a maritime republic and territories around the Adriatic and eastern Mediterranean. Its source polygon is a broad historical reconstruction.'),('papal-states','Papal States','The pope exercised territorial rule in central Italy. Rome also became a major centre of Renaissance patronage.'),('kingdom-of-france','Kingdom of France','France was a kingdom within a politically divided Europe. The ca. 1450 snapshot belongs near the end of the Hundred Years’ War.'),('kingdom-of-portugal','Kingdom of Portugal','Portugal was a separate kingdom on the Atlantic edge of Europe. Its overseas expansion belongs to the broader fifteenth-century setting.'),('ottoman-empire','Ottoman Empire','The Ottoman state held lands in Anatolia and the Balkans. Constantinople remains outside its territory in this pre-1453 snapshot.'),('kingdom-of-naples','Kingdom of Naples','Southern mainland Italy formed a kingdom distinct from the Papal States and northern Italian political centres.')]:region(id,name,fact)
  edition['background']=[{'label':'A cultural movement, many states','text':'Renaissance Europe contained courts, kingdoms, republics and city-states. Humanist study and artistic experimentation spread unevenly across these political boundaries.','source':rena},{'label':'A dated snapshot','text':'Boundaries represent ca. 1450. Constantinople has not yet fallen to the Ottomans; later artistic achievements are described with their dates. Italian city-state boundaries are generalized in this map source.','source':source}]
  events=[('1401','The Florentine baptistery door competition marks a celebrated moment in early Renaissance art.'),('1434','Cosimo de’ Medici consolidates his position in Florence.'),('c. 1450','The political snapshot used for this map; Alberti works at Rimini.'),('1453','Constantinople falls to the Ottoman army, after this map’s date.'),('1450s','Gutenberg’s printing enterprise produces the Gutenberg Bible.'),('1469','Lorenzo de’ Medici rises to power in Florence.')]
 edition['contextTitle']='Life and connections';edition['timelineTitle']='The Viking Age through time' if era=='viking' else 'Renaissance milestones';edition['timelineSource']=met if era=='viking' else 'https://www.metmuseum.org/-/media/files/learn/for-educators/publications-for-educators/renaissance.pdf';edition['timeline']=[{'date':d,'text':t} for d,t in events]
 edition['caption']=('VIKING AGE · c. AD 1000' if era=='viking' else 'RENAISSANCE EUROPE · c. AD 1450')
 edition['sceneSymbols']=data.get(era,{}).get('sceneSymbols',[])
 data[era]=edition
(out/'historical.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
print('Built Viking Age: 16 prompts; Renaissance: 18 prompts.')
